param(
    [string]$ProjectRoot = (Get-Location).Path
)

$ErrorActionPreference = "Stop"
$projectRoot = (Resolve-Path -LiteralPath $ProjectRoot).Path
$timestamp = Get-Date -Format "yyyyMMdd-HHmmss"
$backupRoot = Join-Path $projectRoot "local-backups\phase7b2-management-ui-$timestamp"
$tempPatcher = Join-Path $env:TEMP "patch_phase7b2_$timestamp.py"

$mainPath = Join-Path $projectRoot "local_api\main.py"
$databasePath = Join-Path $projectRoot "local_api\database.py"
$managementUiPath = Join-Path $projectRoot "local_api\management_ui.py"
$visualizerPath = Join-Path $projectRoot "visualize_boss_jobs_v11.py"
$dashboardLinkPath = Join-Path $projectRoot "dashboard_management_link_v13.py"
$dashboardPath = Join-Path $projectRoot "output\visualization_v1_1\visual_dashboard_v11.html"
$offlineTestPath = Join-Path $projectRoot "test_phase7b2_offline.py"
$apiTestPath = Join-Path $projectRoot "test_phase7b2_api.py"
$docPath = Join-Path $projectRoot "docs\phase7b2-management-ui.md"

function Write-Base64File {
    param(
        [Parameter(Mandatory = $true)]
        [string]$Path,

        [Parameter(Mandatory = $true)]
        [string]$Base64
    )

    $parent = Split-Path -Parent $Path

    if ($parent -and -not (Test-Path -LiteralPath $parent)) {
        New-Item `
            -ItemType Directory `
            -Force `
            -Path $parent |
            Out-Null
    }

    [System.IO.File]::WriteAllBytes(
        $Path,
        [System.Convert]::FromBase64String($Base64)
    )
}

function Backup-FileIfExists {
    param(
        [Parameter(Mandatory = $true)]
        [string]$Path,

        [Parameter(Mandatory = $true)]
        [string]$RelativePath
    )

    if (-not (Test-Path -LiteralPath $Path)) {
        return
    }

    $destination = Join-Path $backupRoot $RelativePath
    $parent = Split-Path -Parent $destination

    if (-not (Test-Path -LiteralPath $parent)) {
        New-Item `
            -ItemType Directory `
            -Force `
            -Path $parent |
            Out-Null
    }

    Copy-Item `
        -LiteralPath $Path `
        -Destination $destination `
        -Force
}

function Test-LocalPort {
    param([int]$Port)

    $client = New-Object System.Net.Sockets.TcpClient

    try {
        $result = $client.BeginConnect(
            "127.0.0.1",
            $Port,
            $null,
            $null
        )

        $connected =
            $result.AsyncWaitHandle.WaitOne(350)

        if (-not $connected) {
            return $false
        }

        $client.EndConnect($result)
        return $true
    }
    catch {
        return $false
    }
    finally {
        $client.Close()
    }
}

Write-Host ""
Write-Host "============================================================" -ForegroundColor Cyan
Write-Host "Job Market Reality Check - Phase 7B.2" -ForegroundColor Cyan
Write-Host "Dashboard job management center" -ForegroundColor Cyan
Write-Host "============================================================" -ForegroundColor Cyan

if (Test-LocalPort -Port 8765) {
    throw "Port 8765 is active. Stop run_local_api.ps1 with Ctrl+C, then run this installer again."
}

$requiredFiles = @(
    $mainPath,
    $databasePath,
    (Join-Path $projectRoot "local_api\management.py"),
    $visualizerPath,
    (Join-Path $projectRoot "dashboard_ux_v12.py"),
    $dashboardPath
)

$missingFiles = $requiredFiles | Where-Object {
    -not (Test-Path -LiteralPath $_)
}

if ($missingFiles) {
    Write-Host "Missing required files:" -ForegroundColor Red

    $missingFiles | ForEach-Object {
        Write-Host "  $_"
    }

    throw "Phase 7B.2 was not installed."
}

Write-Host "`n[1/7] Backing up source, UI and current dashboard..." -ForegroundColor Yellow

New-Item `
    -ItemType Directory `
    -Force `
    -Path $backupRoot |
    Out-Null

Backup-FileIfExists `
    -Path $mainPath `
    -RelativePath "local_api\main.py"

Backup-FileIfExists `
    -Path $databasePath `
    -RelativePath "local_api\database.py"

Backup-FileIfExists `
    -Path $managementUiPath `
    -RelativePath "local_api\management_ui.py"

Backup-FileIfExists `
    -Path $visualizerPath `
    -RelativePath "visualize_boss_jobs_v11.py"

Backup-FileIfExists `
    -Path $dashboardLinkPath `
    -RelativePath "dashboard_management_link_v13.py"

Backup-FileIfExists `
    -Path $dashboardPath `
    -RelativePath "output\visualization_v1_1\visual_dashboard_v11.html"

Write-Host "Backup: $backupRoot" -ForegroundColor DarkGray

Write-Host "`n[2/7] Writing management center UI..." -ForegroundColor Yellow

Write-Base64File `
    -Path $managementUiPath `
    -Base64 ""

Write-Base64File `
    -Path $dashboardLinkPath `
    -Base64 ""

Write-Base64File `
    -Path $offlineTestPath `
    -Base64 ""

Write-Base64File `
    -Path $apiTestPath `
    -Base64 ""

Write-Base64File `
    -Path $docPath `
    -Base64 ""

Write-Host "`n[3/7] Patching FastAPI, export rules and visualizer..." -ForegroundColor Yellow

Write-Base64File `
    -Path $tempPatcher `
    -Base64 ""

Set-Location $projectRoot
$env:PYTHONUTF8 = "1"

python $tempPatcher

if ($LASTEXITCODE -ne 0) {
    throw "Phase 7B.2 source patch failed."
}

Remove-Item `
    -LiteralPath $tempPatcher `
    -Force `
    -ErrorAction SilentlyContinue

Write-Host "`n[4/7] Running Python syntax checks..." -ForegroundColor Yellow

python -m py_compile `
    ".\local_api\management_ui.py" `
    ".\local_api\main.py" `
    ".\local_api\database.py" `
    ".\dashboard_management_link_v13.py" `
    ".\visualize_boss_jobs_v11.py" `
    ".\test_phase7b2_offline.py" `
    ".\test_phase7b2_api.py"

if ($LASTEXITCODE -ne 0) {
    throw "Python syntax check failed."
}

Write-Host "`n[5/7] Running isolated UI and export tests..." -ForegroundColor Yellow

python ".\test_phase7b2_offline.py"

if ($LASTEXITCODE -ne 0) {
    throw "Phase 7B.2 offline smoke test failed."
}

Write-Host "`n[6/7] Adding management link to current dashboard..." -ForegroundColor Yellow

python -c "from pathlib import Path; from dashboard_management_link_v13 import enhance_management_link; print(enhance_management_link(Path(r'$dashboardPath')))"

if ($LASTEXITCODE -ne 0) {
    throw "Current dashboard link enhancement failed."
}

Write-Host "`n[7/7] Verifying routes and generated markers..." -ForegroundColor Yellow

python -c "from local_api.main import app; paths={route.path for route in app.routes}; assert '/manage' in paths; print('Phase 7B.2 route verification passed.')"

if ($LASTEXITCODE -ne 0) {
    throw "Management page route verification failed."
}

$dashboardText = Get-Content `
    -LiteralPath $dashboardPath `
    -Raw `
    -Encoding UTF8

if (-not $dashboardText.Contains("job-management-link")) {
    throw "Dashboard management link marker is missing."
}

$visualizerText = Get-Content `
    -LiteralPath $visualizerPath `
    -Raw `
    -Encoding UTF8

if (-not $visualizerText.Contains("enhance_management_link(DASHBOARD_FILE)")) {
    throw "Future dashboard management link integration is missing."
}

Write-Host ""
Write-Host "============================================================" -ForegroundColor Green
Write-Host "Phase 7B.2 installation passed" -ForegroundColor Green
Write-Host "============================================================" -ForegroundColor Green
Write-Host "Backup: $backupRoot"
Write-Host "Management page: http://127.0.0.1:8765/manage"
Write-Host "Documentation: $docPath"
Write-Host ""
Write-Host "Next verification:" -ForegroundColor Cyan
Write-Host "1. Start run_local_api.ps1."
Write-Host "2. Open http://127.0.0.1:8765/manage."
Write-Host "3. Paste the API token once and connect."
Write-Host "4. Test status editing, notes, archive and bulk actions."
Write-Host "5. Run python .\test_phase7b2_api.py in another window."
Write-Host ""
Write-Host "The browser extension collection flow was not changed."
